import json,html
from pathlib import Path
b=Path(__file__).parent;a=b/'assets';cuts=json.loads((a/'proposed-cuts.json').read_text())['cuts'];sil=json.loads((a/'source.silence-edl.json').read_text());fmt=lambda t:f'{int(t//60):02d}:{t%60:05.2f}'
removed=sum(c['end']-c['start'] for c in cuts)
md=['# Blender physics tutorial — proposed cuts','',f'Source: **2026-09-16 20-27-21.mov** · {fmt(sil["source_duration"])} · Original 3840×1080 screen/camera layout.','',f'Silence-only plan: **{fmt(sil["edited_duration"])}**. The **{len(cuts)} proposed mistake cuts** remove approximately **{removed:.1f} additional seconds**, for an estimated **{fmt(sil["edited_duration"]-removed)}** finished edit. Timing may change slightly during verification.','',f'Recommendation: apply all {len(cuts)} cuts below. Each is located by its exact words and the following retained take.','', 'Preserved: complete explanations, comparisons, simulation examples, natural filler, emphasis such as “very, very similar,” and the grammatical handoff “playing these, these all have…” The repeated warm-up greeting is proposed for removal. The spoken “delete that” request is included in cut 27.','', '| # | Source time | Remove | Keep following |','|---|---|---|---|']
rows=[]
for i,c in enumerate(cuts,1):
 md.append(f'| {i} | {fmt(c["source_start"])} | {c["removes"]} | {c["keeps"]} |');rows.append(f'<tr><td>{i}</td><td><button data-t="{max(0,c["source_start"]-1.5)}">{fmt(c["source_start"])}</button></td><td>{html.escape(c["removes"])}</td><td>{html.escape(c["keeps"])}</td></tr>')
md+=['','## Status','','Transcription, stretched-token check, silence plan, mechanical candidate review and full editorial source read complete. Mistake cuts are proposed only; user approval is pending. Final rendering, fresh transcription and three-pass verification follow approval.']
(b/'CUT-REVIEW.md').write_text('\n'.join(md)+'\n')
(b/'review.html').write_text('''<!doctype html><meta charset="utf-8"><title>Blender physics tutorial — cut review</title><style>body{background:#111820;color:#e7edf6;font:16px/1.5 system-ui;max-width:1250px;margin:40px auto;padding:0 24px}video{width:100%;position:sticky;top:0;max-height:42vh;background:black}table{border-collapse:collapse;width:100%}td,th{padding:12px;border-bottom:1px solid #344050;text-align:left;vertical-align:top}button,a{color:#99cfff}button{background:#223349;border:1px solid #527093;border-radius:5px;padding:5px;cursor:pointer}h1{font-size:28px}.sub{color:#a9b7c8}</style><h1>Blender physics tutorial — proposed mistake cuts</h1><p class="sub">42 reviewed cuts · Click a time to play the original with context.</p><p><a href="CUT-REVIEW.md">Written recommendations</a></p><video id="v" src="assets/source.mov" controls preload="metadata"></video><table><thead><tr><th>#</th><th>Source</th><th>Remove</th><th>Keep following</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table><script>const v=document.getElementById('v');document.querySelectorAll('button').forEach(b=>b.onclick=()=>{v.currentTime=Number(b.dataset.t);v.play()})</script>''')
(b/'meta.json').write_text(json.dumps(dict(title='GPT-6 Astra Blender Physics Tests',source='2026-09-16 20-27-21.mov',width=3840,height=1080,fps=30,pipeline=['cut-silences','cut-mistakes','verify-cuts'],status='awaiting-cut-approval',proposed_cuts=len(cuts),source_seconds=sil['source_duration'],estimated_final_seconds=sil['edited_duration']-removed),indent=2))
print('\n'.join(md[:9]))
